-- Celestial Bodies Database
-- Rebuilds the universe database: galaxies, stars, planets, moons and comets.
DROP DATABASE IF EXISTS universe;
CREATE DATABASE universe;
\c universe
CREATE TABLE galaxy(galaxy_id SERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, description TEXT NOT NULL, has_life BOOLEAN NOT NULL, age_in_millions_of_years INT NOT NULL, distance_from_earth NUMERIC);
CREATE TABLE star(star_id SERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, description TEXT NOT NULL, has_life BOOLEAN NOT NULL, is_spherical BOOLEAN NOT NULL, age_in_millions_of_years INT, distance_from_earth NUMERIC, galaxy_id INT NOT NULL REFERENCES galaxy(galaxy_id));
CREATE TABLE planet(planet_id SERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, description TEXT NOT NULL, has_life BOOLEAN NOT NULL, is_spherical BOOLEAN NOT NULL, age_in_millions_of_years INT, distance_from_earth NUMERIC, star_id INT NOT NULL REFERENCES star(star_id));
CREATE TABLE moon(moon_id SERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, description TEXT NOT NULL, has_life BOOLEAN NOT NULL, is_spherical BOOLEAN NOT NULL, age_in_millions_of_years INT, diameter_km INT, planet_id INT NOT NULL REFERENCES planet(planet_id));
CREATE TABLE comet(comet_id SERIAL PRIMARY KEY, name VARCHAR(100) UNIQUE NOT NULL, description TEXT NOT NULL, has_tail BOOLEAN NOT NULL, is_spherical BOOLEAN NOT NULL, orbital_period_years INT, diameter_km INT, distance_from_earth NUMERIC);
